<?php $title="Create Offer";require "includes/header.php";if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$conn->prepare("INSERT INTO offers(title,audience,discount,status) VALUES(?,?,?,?)");$d=(int)$_POST["discount"];$s->bind_param("ssis",$_POST["title"],$_POST["audience"],$d,$_POST["status"]);$s->execute();go("offers.php");}?><div class="card"><h2>Create Smart Offer</h2><form method="post"><label>Title</label><input name="title" required><label>Audience</label><select name="audience"><option>New Riders</option><option>Adventure Riders</option><option>Premium Customers</option><option>Inactive Customers</option></select><label>Discount %</label><input name="discount" type="number" value="10"><label>Status</label><select name="status"><option>Active</option><option>Draft</option><option>Scheduled</option></select><button class="btn primary">Create Offer</button></form></div><?php require "includes/footer.php";?>